* {
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  margin: 0;
  padding: 12px;
  color: #1e293b;
  background: transparent;
}

.section {
  margin-bottom: 20px;
}

.section-header {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: #475569;
  padding-bottom: 6px;
  border-bottom: 1px solid #e2e8f0;
  margin-bottom: 8px;
}

.doc-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.doc-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
  color: #0f172a;
  font-size: 14px;
}

.doc-row:hover {
  background-color: #f1f5f9;
  color: #0284c7;
}

.doc-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  font-size: 13px;
  border-radius: 4px;
  background-color: #e0f2fe;
  color: #0369a1;
  flex-shrink: 0;
}

.doc-title {
  flex-grow: 1;
  font-weight: 500;
}

